import { describe, it, expect, beforeAll } from 'vitest';
import fs from 'fs';
import path from 'path';
import {
  prisma,
  HistFormat,
  BowlingStyle,
  getTeamForm,
  getHeadToHead,
  getTeamComparison,
  getVenueStats,
  getPaceSpin,
  getRecentAtVenue,
} from '../src/index.js';
import { importMatchData } from '../../../scripts/import-cricsheet.js';

const FIXTURES_DIR = path.resolve(__dirname, '../stats/__fixtures__');

describe('Query Layer Tests (Step 5)', () => {
  let teamAusId: string;
  let teamSLId: string;
  let venueMcgId: string;

  beforeAll(async () => {
    // Import 3 fixtures
    const t20iData = JSON.parse(fs.readFileSync(path.join(FIXTURES_DIR, 'sample_t20i.json'), 'utf8'));
    const soData = JSON.parse(fs.readFileSync(path.join(FIXTURES_DIR, 'sample_super_over.json'), 'utf8'));
    const dlsData = JSON.parse(fs.readFileSync(path.join(FIXTURES_DIR, 'sample_dls_or_superover.json'), 'utf8'));

    await importMatchData('1001349', t20iData);
    await importMatchData('1082625', soData);
    await importMatchData('1043991', dlsData);

    const aus = await prisma.team.findFirst({ where: { name: 'Australia' } });
    const sl = await prisma.team.findFirst({ where: { name: 'Sri Lanka' } });
    const mcg = await prisma.venue.findFirst({ where: { name: { contains: 'Melbourne' } } });

    teamAusId = aus!.id;
    teamSLId = sl!.id;
    venueMcgId = mcg!.id;

    // Ensure bowlerStats exist if match 1001349 was inserted before bowlerStats was implemented
    const bStatsCount = await prisma.histBowlerStat.count({ where: { match: { venueId: venueMcgId } } });
    if (bStatsCount === 0) {
      const match = await prisma.histMatch.findUnique({ where: { cricsheetMatchId: '1001349' } });
      if (match) {
        const bowlers = await prisma.player.findMany({ take: 6 });
        for (const b of bowlers) {
          await prisma.histBowlerStat.create({
            data: {
              matchId: match.id,
              inningsNumber: 1,
              bowlerId: b.id,
              balls: 24,
              runsConceded: 28,
              wickets: 1,
            },
          });
        }
      }
    }
  });

  it('1. getTeamForm returns recent matches with scores and results', async () => {
    const form = await getTeamForm(teamSLId, 5, { prisma });
    expect(form.teamId).toBe(teamSLId);
    expect(form.matches.length).toBeGreaterThanOrEqual(1);

    const match = form.matches[0];
    expect(match.result).toBe('W');
    expect(match.vsTeam.name).toBe('Australia');
    expect(match.teamRuns).toBe(172);
    expect(match.opponentRuns).toBe(168);
    expect(match.marginText).toContain('5 wickets');
  });

  it('2. getHeadToHead returns null if sample < 2, or full stats if sample >= 2', async () => {
    // Only 1 match between Aus and SL in DB right now -> should return null (insufficient sample)
    const h2hSingle = await getHeadToHead(teamAusId, teamSLId, 10, { prisma });
    expect(h2hSingle).toBeNull();

    // Create a 2nd mock historical match between Aus & SL to test sample >= 2
    const secondMatch = await prisma.histMatch.create({
      data: {
        cricsheetMatchId: 'mock_h2h_2',
        date: new Date('2024-01-01'),
        format: HistFormat.T20I,
        teamType: 'international',
        gender: 'male',
        venueId: venueMcgId,
        teamAId: teamAusId,
        teamBId: teamSLId,
        winnerId: teamAusId,
        resultType: 'WIN',
        marginType: 'RUNS',
        marginValue: 20,
        innings: {
          create: [
            { inningsNumber: 1, battingTeamId: teamAusId, runs: 180, wickets: 5, balls: 120, oversDisplay: '20.0' },
            { inningsNumber: 2, battingTeamId: teamSLId, runs: 160, wickets: 8, balls: 120, oversDisplay: '20.0' },
          ],
        },
      },
    });

    const h2h = await getHeadToHead(teamAusId, teamSLId, 10, { prisma });
    expect(h2h).not.toBeNull();
    expect(h2h?.totalMatches).toBe(2);
    expect(h2h?.teamAWins).toBe(1);
    expect(h2h?.teamBWins).toBe(1);
    expect(h2h?.recentMatches.length).toBe(2);

    // Clean up mock match
    await prisma.histMatch.delete({ where: { id: secondMatch.id } });
  });

  it('3. getTeamComparison calculates win % and batting 1st/2nd averages', async () => {
    const comp = await getTeamComparison(teamSLId, teamAusId, { prisma });
    expect(comp.sampleSizeA).toBeGreaterThanOrEqual(1);
    expect(comp.teamA.teamName).toBe('Sri Lanka');
    expect(comp.teamB.teamName).toBe('Australia');
    // Aus batted 1st in 1001349 (168 runs)
    expect(comp.teamB.avgScoreBattingFirst).toBe(168);
    // SL batted 2nd in 1001349 (172 runs)
    expect(comp.teamA.avgScoreBattingSecond).toBe(172);
  });

  it('4. getVenueStats returns venue aggregates or null if matches < 3', async () => {
    // Only 1 match at MCG -> should return null (sample < 3)
    const vsMCG1 = await getVenueStats(venueMcgId, { prisma });
    expect(vsMCG1).toBeNull();

    // Create 2 more matches at MCG to make sample = 3
    const m2 = await prisma.histMatch.create({
      data: {
        cricsheetMatchId: 'mock_mcg_2',
        date: new Date('2023-01-01'),
        format: HistFormat.T20I,
        teamType: 'international',
        gender: 'male',
        venueId: venueMcgId,
        teamAId: teamAusId,
        teamBId: teamSLId,
        battingFirstTeamId: teamAusId,
        winnerId: teamAusId,
        tossWinnerId: teamAusId,
        resultType: 'WIN',
        innings: {
          create: [
            { inningsNumber: 1, battingTeamId: teamAusId, runs: 190, wickets: 4, balls: 120, oversDisplay: '20.0' },
            { inningsNumber: 2, battingTeamId: teamSLId, runs: 150, wickets: 9, balls: 120, oversDisplay: '20.0' },
          ],
        },
      },
    });

    const m3 = await prisma.histMatch.create({
      data: {
        cricsheetMatchId: 'mock_mcg_3',
        date: new Date('2023-02-01'),
        format: HistFormat.T20I,
        teamType: 'international',
        gender: 'male',
        venueId: venueMcgId,
        teamAId: teamAusId,
        teamBId: teamSLId,
        battingFirstTeamId: teamAusId,
        winnerId: teamSLId,
        tossWinnerId: teamSLId,
        resultType: 'WIN',
        innings: {
          create: [
            { inningsNumber: 1, battingTeamId: teamAusId, runs: 140, wickets: 10, balls: 110, oversDisplay: '18.2' },
            { inningsNumber: 2, battingTeamId: teamSLId, runs: 144, wickets: 3, balls: 100, oversDisplay: '16.4' },
          ],
        },
      },
    });

    const vsMCG3 = await getVenueStats(venueMcgId, { prisma });
    expect(vsMCG3).not.toBeNull();
    expect(vsMCG3?.totalMatches).toBe(3);
    expect(vsMCG3?.wonBattingFirst).toBe(1);
    expect(vsMCG3?.wonBattingSecond).toBe(2);
    expect(vsMCG3?.highestScoreChased).toBe(172);

    // Clean up
    await prisma.histMatch.deleteMany({ where: { id: { in: [m2.id, m3.id] } } });
  });

  it('5. getPaceSpin accurately respects classification threshold (>20% unclassified = insufficient)', async () => {
    // Reset bowlers at MCG to UNKNOWN for clean test run
    await prisma.player.updateMany({
      where: { bowlerStats: { some: { match: { venueId: venueMcgId } } } },
      data: { bowlingStyle: BowlingStyle.UNKNOWN },
    });

    // Check pace vs spin at MCG with unclassified bowlers
    const paceSpinBefore = await getPaceSpin(venueMcgId, 10, { prisma });
    expect(paceSpinBefore.available).toBe(false);
    if (!paceSpinBefore.available) {
      expect(paceSpinBefore.reason).toBe('insufficient_bowler_classification');
    }

    // Now classify the bowlers in MCG match:
    // Bowlers in sample_t20i: SL bowlers (Malinga = pace, Prasanna = spin, Gunaratne = pace, Lakmal = pace)
    // Aus bowlers (Turner, Starc, etc.)
    const bowlers = await prisma.player.findMany({
      where: { bowlerStats: { some: { match: { venueId: venueMcgId } } } },
    });

    for (const b of bowlers) {
      const isSpin = b.name.includes('Prasanna') || b.name.includes('Zampa') || b.name.includes('Head');
      await prisma.player.update({
        where: { id: b.id },
        data: { bowlingStyle: isSpin ? BowlingStyle.SPIN : BowlingStyle.PACE },
      });
    }

    const paceSpinAfter = await getPaceSpin(venueMcgId, 10, { prisma });
    expect(paceSpinAfter.available).toBe(true);
    if (paceSpinAfter.available) {
      expect(paceSpinAfter.totalWickets).toBeGreaterThan(0);
      expect(paceSpinAfter.paceWickets + paceSpinAfter.spinWickets).toBe(paceSpinAfter.totalWickets);
      expect(paceSpinAfter.paceWicketPct + paceSpinAfter.spinWicketPct).toBe(100);
      expect(paceSpinAfter.paceEconomy).toBeGreaterThan(0);
    }
  });

  it('6. getRecentAtVenue returns formatted scorecards and margins', async () => {
    const recent = await getRecentAtVenue(venueMcgId, 3, { prisma });
    expect(recent.venueId).toBe(venueMcgId);
    expect(recent.matches.length).toBe(1);
    const m = recent.matches[0];
    expect(m.teamA.score).toContain('168');
    expect(m.teamB.score).toContain('172');
    expect(m.winnerName).toBe('Sri Lanka');
  });
});
